template <typename T, typename U>
struct TypeID {
    static constexpr int Value = 0; // Primary template (Generic)
};

// Full Specialization: Exact match
template <>
struct TypeID<int, float> {
    static constexpr int Value = 1;
};

// Partial Specialization 1: Second argument is a pointer (U=V*)
template <typename T, typename V>
struct TypeID<T, V*> {
    static constexpr int Value = 2;
};

// Partial Specialization 2: Arguments are the same type (T=U)
template <typename T>
struct TypeID<T, T> {
    static constexpr int Value = 3;
};

// Compile-time evaluation example
constexpr int ID_A = TypeID<char, bool>::Value;     // 0
constexpr int ID_B = TypeID<int, float>::Value;    // 1
constexpr int ID_C = TypeID<double, int*>::Value;  // 2
constexpr int ID_D = TypeID<long, long>::Value;    // 3
